import assert from 'node:assert/strict';
const attrs=(tag:string)=>Object.fromEntries([...tag.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],m[2]]));
const content=(s:string)=>s.replace(/&gt;/g,'>').replace(/&lt;/g,'<').replace(/&amp;/g,'&');
const rectangles=[['whole',20,20,860,540],['outline',300,270,40,45],['vehicle',315,282,10,22],['frame',430,50,430,480],['body',590,150,110,205],['controller',608,236,74,48],['L',562,326,30,54],['R',698,326,30,54],['L',596,335,35,35],['R',659,335,35,35]];
const leaders=['M 563 135 L 590 135','M 745 135 L 700 135','M 745 190 L 675 190','M 785 305 L 715 340','M 785 305 L 575 340','M 580 395 L 598 375','M 733 395 L 686 375'];
const expectedRows=[['上げる','下げる','上げる','下げる'],['上げる','下げる','下げる','上げる'],['下げる','上げる','上げる','下げる'],['下げる','上げる','下げる','上げる']];
export function autumnLineDescription(v:number){return '黒色の円の全体図と、その右側を上向きに走る車の拡大図。車の前方にセンサLが左、センサRが右にあり、中央の前輪、制御部、左右の後輪とそれぞれのモータL・Rが示される。二つのセンサの間から車体の下へ黒色の帯が続き、進行方向の矢印は上向き。'+(v===0?'黒色に掛かる比率が大きいほど出力値は小さい。':'黒色に掛かる比率が大きいほど出力値は大きい。')+'解答群の表は、センサL出力値＞センサR出力値のときと、センサL出力値＜センサR出力値のときについて、モータL・モータRの回転速度を示す。アは上げる・下げる・上げる・下げる。イは上げる・下げる・下げる・上げる。ウは下げる・上げる・上げる・下げる。エは下げる・上げる・下げる・上げる。出力値が一致するときには両モータを初期値に戻す。';}
/** Reviewed source geometry plus actual rendered coordinates. Data tags identify
 * elements; all x/y/vertices/labels and marker target are independently fixed. */
export function readAutumnLineSvg(svg:string,v:number){
 const svgTag=attrs(svg.match(/<svg\b[^>]*>/)![0]);assert.equal(svgTag.viewBox,'0 0 900 1000');assert.equal(svgTag.role,'img');const title=svg.match(/<title id="([^"]+)">([^<]*)<\/title>/)!,desc=svg.match(/<desc id="([^"]+)">([^<]*)<\/desc>/)!;assert.equal(content(title[2]),'円に沿って走る車と制御方法の解答群');assert.equal(content(desc[2]),autumnLineDescription(v));assert.equal(svgTag['aria-labelledby'],title[1]);assert.equal(svgTag['aria-describedby'],desc[1]);
 const model=svg.slice(svg.indexOf('<g class="physical-model"'),svg.indexOf('<g data-motor-table'));assert(model.includes('aria-hidden="true"'));
 const rects=[...model.matchAll(/<rect\b[^>]*>/g)].map(m=>{const a=attrs(m[0]);return[Object.entries(a).find(([k])=>k.startsWith('data-'))![1],Number(a.x),Number(a.y),Number(a.width),Number(a.height)];});assert.deepEqual(rects,rectangles);
 const circleTags=[...model.matchAll(/<circle\b[^>]*>/g)].map(m=>attrs(m[0]));assert.equal(circleTags.length,2);assert.deepEqual(circleTags.map(a=>[a['data-track-circle']??a['data-wheel'],Number(a.cx),Number(a.cy),Number(a.r)]),[['whole',190,290,130],['front',645,195,26]]);
 const sensors=[...model.matchAll(/<polygon\b[^>]*>/g)].map(m=>attrs(m[0]));assert.deepEqual(sensors.map(a=>[a['data-sensor'],a.points]),[['L','590,150 602,124 614,150'],['R','676,150 688,124 700,150']]);const sensorX=sensors.map(a=>a.points.split(' ')[1].split(',').map(Number)[0]);assert(sensorX[0]<sensorX[1]);const wheelX=rects.filter(r=>['L','R'].includes(String(r[0]))&&r[4]===54).map(r=>Number(r[1]));assert(wheelX[0]<wheelX[1]);
 const modelLines=[...model.matchAll(/<line\b[^>]*>/g)].map(m=>{const a=attrs(m[0]);return[Number(a.x1),Number(a.y1),Number(a.x2),Number(a.y2)];});assert.deepEqual(modelLines,[[637,178,637,212],[645,178,645,212],[653,178,653,212],[592,352,596,352],[694,352,698,352],[570,333,570,373],[577,333,577,373],[584,333,584,373],[706,333,706,373],[713,333,713,373],[720,333,720,373]]);
 const allPaths=[...model.matchAll(/<path\b[^>]*>/g)].map(m=>attrs(m[0]));assert.equal(allPaths.find(a=>a['data-enlargement']==='connector')!.d,'M 340 270 L 430 230 M 340 315 L 430 350');assert.equal(allPaths.find(a=>a['data-black-band'])!.d,'M 595 50 C 640 190 640 390 595 530 L 665 530 C 710 390 710 190 665 50 Z');const forward=allPaths.find(a=>a['data-forward'])!;assert.equal(forward.d,'M 730 100 L 730 55');const travel=[100,55];assert(travel[1]<travel[0]);
 const marker=attrs(svg.match(/<marker\b[^>]*>/)![0]);assert.equal(marker.orient,'auto');assert.equal(marker.viewBox,'0 0 10 10');assert.equal(marker.refX,'9');assert.equal(marker.refY,'5');assert.match(svg,/<path d="M 1 1 L 9 5 L 1 9" fill="none" stroke="var\(--visual-line-track\)" stroke-width="1.5">/);assert.equal(forward['marker-end'],`url(#${marker.id})`);const actualLeaders=allPaths.filter(a=>a['data-label-leader']);assert.deepEqual(actualLeaders.map(a=>a.d),leaders);assert(actualLeaders.every(a=>a['marker-end']===`url(#${marker.id})`));
 const modelWords=[...model.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>{const a=attrs(m[1]);return[Number(a.x),Number(a.y),a['text-anchor'],content(m[2])];});assert.deepEqual(modelWords,[[560,135,'end','センサL'],[750,135,'start','センサR'],[770,75,'start','進行方向'],[750,190,'start','前輪'],[643,260,'middle','制御部'],[790,305,'start','後輪'],[520,405,'start','モータL'],[725,405,'start','モータR'],[510,480,'start','円']]);
 const table=svg.slice(svg.indexOf('<g data-motor-table'));const tableRects=[...table.matchAll(/<rect\b[^>]*>/g)].map(m=>{const a=attrs(m[0]);return[Number(a.x),Number(a.y),Number(a.width),Number(a.height),a.fill];});assert.deepEqual(tableRects,[[90,610,780,115,'none'],[40,725,830,240,'none']]);const grid=[...table.matchAll(/<line\b[^>]*>/g)].map(m=>{const a=attrs(m[0]);return[Number(a.x1),Number(a.y1),Number(a.x2),Number(a.y2)];});assert.deepEqual(grid,[[480,610,480,965],[90,675,870,675],[285,675,285,965],[675,675,675,965],[90,725,90,965],[40,785,870,785],[40,845,870,845],[40,905,870,905]]);const tableTexts=[...table.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({a:attrs(m[1]),text:content(m[2])}));assert.deepEqual(tableTexts.slice(0,4).map(t=>[Number(t.a.x),Number(t.a.y),t.text]),[[285,634,'センサL出力値＞センサR出力値'],[285,659,'のとき'],[675,634,'センサL出力値＜センサR出力値'],[675,659,'のとき']]);for(let i=0;i<4;i++){assert.deepEqual(tableTexts.slice(4+2*i,6+2*i).map(t=>[Number(t.a.x),Number(t.a.y),t.text]),[[187.5+195*i,691,'モータ'+('LRLR'[i])],[187.5+195*i,715,'回転速度']]);}
 const rows=expectedRows.map(()=>[] as string[]);for(const t of tableTexts.filter(t=>t.a['data-table-cell'])){const[i,c]=t.a['data-table-cell'].split(',').map(Number);assert.equal(Number(t.a.x),187.5+195*c);assert.equal(Number(t.a.y),755+60*i);assert.equal(t.a['text-anchor'],'middle');rows[i][c]=t.text;}assert.deepEqual(rows,expectedRows);assert.equal(tableTexts.filter(t=>t.a['data-table-cell']).length,16);assert.deepEqual(tableTexts.filter(t=>t.a['data-row-label']).map(t=>[Number(t.a.x),Number(t.a.y),t.text]),[...('アイウエ')].map((x,i)=>[65,755+60*i,x]));
 // Convert output difference to black coverage then actual track side. With the
 // measured L/R layout and forward-up, a track on the right needs L faster/R slower.
 const required=[1,-1].flatMap(outputLDifference=>{const blackLDifference=outputLDifference*(v===0?-1:1),trackOnRight=blackLDifference<0;return trackOnRight?['上げる','下げる']:['下げる','上げる'];});return{rows,required,truth:rows.map(r=>r.every((cell,i)=>cell===required[i])),description:content(desc[2]),sensorX,wheelX};
}
